package com.drafto.app.core

/**
 * Mirror of the gomobile-bound Go types (github.com/.../core).
 * The real implementation is generated by `gomobile bind`; the data classes
 * here mirror the Go structs so the UI layer stays Kotlin-native.
 */
data class Draft(
    val uuid: String,
    val content: String,
    val title: String,
    val tags: List<String>,
    val isFlagged: Boolean,
    val isArchived: Boolean,
    val isTrashed: Boolean,
    val folder: String,
    val createdAt: String,
    val modifiedAt: String,
    val permalink: String,
)

data class Counts(
    val inbox: Int,
    val flagged: Int,
    val archive: Int,
    val trash: Int,
    val all: Int,
)

data class ActionRunResult(
    val uuid: String,
    val createdDraft: Boolean,
    val output: String,
    val copied: String,
)

/** Engine API consumed by the UI. Implemented by FakeEngine (preview) and the
 *  gomobile binding (production). */
interface DraftoEngine {
    fun createDraft(content: String, tags: List<String>, flagged: Boolean): Draft
    fun getDraft(uuid: String): Draft?
    fun queryDrafts(filter: String, search: String, tags: List<String>, limit: Int): List<Draft>
    fun setFlagged(uuid: String, flagged: Boolean): Draft
    fun archiveDraft(uuid: String)
    fun trashDraft(uuid: String)
    fun replaceDraft(uuid: String, content: String): Draft
    fun addTags(uuid: String, tags: List<String>): Draft
    fun runAction(actionName: String, uuid: String): ActionRunResult
    fun listTags(): List<String>
    fun counts(): Counts
    fun registerAction(name: String, stepsJson: String)
}
